const company = $json.company || '';
const jobTitle = $json.job_title || '';
const location = $json.location || '';
const queries = [
  `site:linkedin.com "${company}" recruiter`,
  `site:linkedin.com "${company}" engineering recruiter`,
  `site:linkedin.com "${company}" software recruiter`,
  `site:linkedin.com "${company}" talent acquisition`,
  `site:linkedin.com "${company}" university recruiter`,
  `site:linkedin.com "${company}" hiring manager`,
  `"${company}" recruiting team`,
  `"${company}" engineering manager`,
  `"${company}" talent acquisition`
];
return queries.map(query => ({ json: { company, job_title: jobTitle, location, query } }));

const input = $items('Workflow Input')[0].json;
const company = input.company || '';
const jobTitle = input.job_title || '';
const location = input.location || '';
const recruiters = [];
for (const item of $input.all()) {
  const results = item.json.results || [];
  for (const result of results) {
    const title = result.title || '';
    const url = result.url || '';
    const content = result.content || '';
    const haystack = `${title} ${content}`;
    if (!/recruiter|talent acquisition|hiring manager|engineering manager|university recruiter/i.test(haystack)) continue;
    recruiters.push({
      name: title.split(' - ')[0].trim(),
      role: title,
      location,
      public_email: '',
      linkedin_url: url.includes('linkedin.com') ? url : '',
      team: '',
      experience: content,
      hiring_area: jobTitle,
      source_url: url
    });
  }
}
return [{ json: { ...input, company, job_title: jobTitle, location, recruiters } }];

const input = $items('Normalize Public Candidates')[0].json;
const ranked = $json.recruiters || [];
return [{ json: { ...input, recruiters: ranked.slice(0, 5), best_recruiter: ranked[0] || null } }];
